import React, { useEffect, useRef, useState, useCallback } from "react";
import Chart from "chart.js/auto";

const DATA_PATH = "/smogon_csv/";

export default function ComUsage() {
  const chartRef = useRef(null);
  const canvasRef = useRef(null);

  const [files, setFiles] = useState([]);
  const [pokemonList, setPokemonList] = useState([]);
  const [filteredList, setFilteredList] = useState([]);
  const [search, setSearch] = useState("");

  const [selectedPokemon, setSelectedPokemon] = useState("");
  const [compareList, setCompareList] = useState([]);
  const [selectedGen, setSelectedGen] = useState("9");
  const [menuOpen, setMenuOpen] = useState(false);

  // 📂 Load file list
  useEffect(() => {
    fetch(DATA_PATH + "files.json")
      .then(res => res.json())
      .then(data => setFiles(data.files));
  }, []);

  const loadCSV = async (file) => {
    const res = await fetch(DATA_PATH + file);
    return await res.text();
  };

  const parseCSV = (text) =>
    text.split("\n").slice(1).map(r => r.split(","));

  // 🔥 Build Pokémon list
  useEffect(() => {
    const buildPokemonList = async () => {
      const set = new Set();

      for (let file of files) {
        const text = await loadCSV(file);
        const rows = parseCSV(text);

        rows.forEach(row => {
          if (row[1]) set.add(row[1]);
        });
      }

      const list = Array.from(set).sort();
      setPokemonList(list);
      setFilteredList(list);

      if (!selectedPokemon && list.length) {
        setSelectedPokemon(list[0]);
      }
    };

    if (files.length) buildPokemonList();
  }, [files]);

  // 🔍 Filter Pokémon list based on search
  useEffect(() => {
    const filtered = pokemonList.filter(p =>
      p.toLowerCase().includes(search.toLowerCase())
    );
    setFilteredList(filtered);
  }, [search, pokemonList]);

  // ➕ Add Pokémon
  const addToCompare = () => {
    if (selectedPokemon && !compareList.includes(selectedPokemon)) {
      setCompareList([...compareList, selectedPokemon]);
    }
  };

  // ❌ Remove Pokémon
  const removeFromCompare = (name) => {
    setCompareList(compareList.filter(p => p !== name));
  };

  // Get usage data for ALL selected Pokémon
  const getUsageData = useCallback(async () => {
    const sortedFiles = [...files].sort();
    let labels = [];

    const datasets = [];

    for (let pokemon of compareList) {
      const data = [];
      const tempLabels = [];

      for (let file of sortedFiles) {
        if (!file.includes(`gen${selectedGen}`)) continue;

        const text = await loadCSV(file);
        const rows = parseCSV(text);

        const match = rows.find(r => r[1] === pokemon);

        if (match) {
          tempLabels.push(file.split("_")[0]);
          data.push(parseFloat(match[2]));
        }
      }

      labels = tempLabels;

      datasets.push({
        label: pokemon,
        data,
        tension: 0.3,
        borderColor: `hsl(${Math.random()*360},70%,50%)`
      });
    }

    return { labels, datasets };
  }, [files, selectedGen, compareList]);

  // Build chart
  useEffect(() => {
    const buildChart = async () => {
      if (compareList.length === 0) return;

      const { labels, datasets } = await getUsageData();

      if (chartRef.current) chartRef.current.destroy();

      chartRef.current = new Chart(canvasRef.current, {
        type: "line",
        data: { labels, datasets },
        options: {
          responsive: true,
          plugins: {
            legend: { position: "top" }
          }
        }
      });
    };

    buildChart();
  }, [getUsageData]);

  return (
    <div>
      <h2>Pokémon Usage Over Time</h2>

      {/* Burger Menu */}
      <div style={{ position: "absolute", top: 20, right: 20 }}>
        <button onClick={() => setMenuOpen(!menuOpen)}>☰</button>
      </div>

      {/* FILTER PANEL */}
      {menuOpen && (
        <div style={{
          position: "absolute",
          top: 60,
          right: 20,
          background: "#eee",
          padding: "15px",
          borderRadius: "8px",
          width: "250px",
          maxHeight: "500px",
          overflowY: "auto"
        }}>
          <h4>Filters</h4>

          {/* Generation */}
          <label>Generation:</label>
          <select
            value={selectedGen}
            onChange={(e) => setSelectedGen(e.target.value)}
          >
            {[6,7,8,9].map(g => (
              <option key={g} value={g}>Gen {g}</option>
            ))}
          </select>

          <br /><br />

          {/* 🔍 SEARCH BAR */}
          <label>Search Pokémon:</label>
          <input
            type="text"
            placeholder="Search..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            style={{ width: "100%" }}
          />

          <br /><br />

          {/* Pokémon list */}
          <label>Select Pokémon:</label>
          <select
            size="5"
            style={{ width: "100%" }}
            value={selectedPokemon}
            onChange={(e) => setSelectedPokemon(e.target.value)}
          >
            {filteredList.map(p => (
              <option key={p} value={p}>{p}</option>
            ))}
          </select>

          <br /><br />

          <button onClick={addToCompare} style={{ width: "100%" }}>
            ➕ Add to Compare
          </button>

          <hr />

          {/* Compare list */}
          <h4>Compare List</h4>
          {compareList.map(p => (
            <div key={p} style={{
              display: "flex",
              justifyContent: "space-between",
              marginBottom: "5px"
            }}>
              <span>{p}</span>
              <button onClick={() => removeFromCompare(p)}>❌</button>
            </div>
          ))}
        </div>
      )}

      <canvas ref={canvasRef}></canvas>
    </div>
  );
}
